const cnForwardFileDrop=(event) => {
    if (!event.dataTransfer.types.includes('Files'))
        return;
    if (!(event.target instanceof Element) || !event.target.closest('.react-flow__edge'))
        return;
    const receiver = event.currentTarget.ownerDocument
        .elementsFromPoint(event.clientX, event.clientY)
        .find((element) => element.closest('.react-flow__node') && event.currentTarget.contains(element));
    if (!receiver)
        return;
    event.preventDefault();
    event.stopPropagation();
    receiver.dispatchEvent(new DragEvent(event.type, {
        bubbles: true,
        cancelable: true,
        composed: event.nativeEvent.composed,
        dataTransfer: event.dataTransfer,
        clientX: event.clientX,
        clientY: event.clientY,
        screenX: event.screenX,
        screenY: event.screenY,
        ctrlKey: event.ctrlKey,
        shiftKey: event.shiftKey,
        altKey: event.altKey,
        metaKey: event.metaKey,
        button: event.button,
        buttons: event.buttons,
        relatedTarget: event.relatedTarget,
    }));
